      /* ——— استاندارد تصویر محصول (سراسری) ———
         نسبت ۴:۵ · خروجی WebP · حداکثر ۳ تصویر · یکی شاخص
         حجم خروجی ≤ ۱۰۰KB · آپلود خام ≤ ۲MB */
      const PRODUCT_IMG = { w: 800, h: 1000, maxBytes: 100000, quality: 0.78, maxPerProduct: 3, maxUploadBytes: 2 * 1024 * 1024 };
      const fileToImage = (file) => new Promise((resolve, reject) => {
        const url = URL.createObjectURL(file);
        const img = new Image();
        img.onload = () => { URL.revokeObjectURL(url); resolve(img); };
        img.onerror = reject;
        img.src = url;
      });
      /** برش مرکز/آفست + تبدیل اجباری به WebP استاندارد */
      const processToProductWebP = async (source, opts = {}) => {
        const img = typeof source === 'string'
          ? await new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = source; })
          : await fileToImage(source);
        const canvas = document.createElement('canvas');
        canvas.width = PRODUCT_IMG.w;
        canvas.height = PRODUCT_IMG.h;
        const ctx = canvas.getContext('2d');
        const scale = opts.scale || Math.max(PRODUCT_IMG.w / img.width, PRODUCT_IMG.h / img.height);
        const dw = img.width * scale;
        const dh = img.height * scale;
        const ox = opts.offsetX != null ? opts.offsetX : (PRODUCT_IMG.w - dw) / 2;
        const oy = opts.offsetY != null ? opts.offsetY : (PRODUCT_IMG.h - dh) / 2;
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, PRODUCT_IMG.w, PRODUCT_IMG.h);
        ctx.drawImage(img, ox, oy, dw, dh);
        let q = PRODUCT_IMG.quality;
        let dataUrl = canvas.toDataURL('image/webp', q);
        // کاهش کیفیت تا زیر ۱۰۰KB بدون افت محسوس
        while (dataUrl.length * 0.75 > PRODUCT_IMG.maxBytes && q > 0.42) {
          q -= 0.05;
          dataUrl = canvas.toDataURL('image/webp', q);
        }
        if (dataUrl.length * 0.75 > PRODUCT_IMG.maxBytes) {
          throw new Error('حجم خروجی WebP بیش از ۱۰۰ کیلوبایت شد؛ از ابزارهای کمکی با برش دقیق‌تر استفاده کنید');
        }
        return { dataUrl, width: PRODUCT_IMG.w, height: PRODUCT_IMG.h, bytes: Math.round(dataUrl.length * 0.75) };
      };
      const [sellerMediaToolOpen, setSellerMediaToolOpen] = useState(false);
      const [mediaToolStep, setMediaToolStep] = useState('upload'); // upload | crop | assign
