      const sendOtp = () => {
        if (authLockedUntil && Date.now() < authLockedUntil) {
          const sec = Math.ceil((authLockedUntil - Date.now()) / 1000);
          setAuthError(`به دلیل تلاش‌های ناموفق، ${toFa(sec)} ثانیه دیگر تلاش کنید`);
          return;
        }
        const phone = onlyDigits(authPhone);
        if (phone.length !== 11 || !phone.startsWith('09')) {
          setAuthError('شماره موبایل معتبر وارد کنید (۱۱ رقم، با ۰۹)');
          return;
        }
        setAuthError('');
        setAuthLoading(true);
        setTimeout(() => {
          setAuthLoading(false);
          // شبیه‌سازی ارسال OTP — کد در UI عمومی نشان داده نمی‌شود (فقط state داخلی دمو)
          const code = String(Math.floor(100000 + Math.random() * 900000));
          setDemoOtpCode(code);
          try { sessionStorage.setItem('demo_otp', code); } catch (_) {}
          setAuthStep('otp');
          setAuthOtp('');
          setAuthOtpTimer(120);
        }, 600);
      };

      const verifyOtp = () => {
        if (authLockedUntil && Date.now() < authLockedUntil) {
          const sec = Math.ceil((authLockedUntil - Date.now()) / 1000);
          setAuthError(`قفل موقت: ${toFa(sec)} ثانیه صبر کنید`);
          return;
        }
        const entered = onlyDigits(authOtp);
        if (entered.length < 4) {
          setAuthError('کد تأیید را کامل وارد کنید');
          return;
        }
        setAuthLoading(true);
        setTimeout(() => {
          setAuthLoading(false);
          const expected = demoOtpCode || (() => { try { return sessionStorage.getItem('demo_otp') || ''; } catch { return ''; } })();
          // دمو: کد ارسال‌شده یا ۱۲۳۴۵۶ — در پروداکشن فقط expected از SMS
          const ok = entered === expected || entered === '123456';
          if (!ok) {
            const fails = authFailCount + 1;
            setAuthFailCount(fails);
            if (fails >= 5) {
              setAuthLockedUntil(Date.now() + 90 * 1000);
              setAuthFailCount(0);
              setAuthError('۵ بار اشتباه. ۹۰ ثانیه قفل شدید');
            } else {
              setAuthError(`کد نادرست است (${toFa(fails)} از ۵)`);
            }
            return;
          }
          setAuthFailCount(0);
          const phone = onlyDigits(authPhone);
          const key = authMode === 'seller' ? 'sellerUser' : 'buyerUser';
          const existing = readSessionUser(key);
          if (existing && existing.phone === phone) {
            const refreshed = persistSession(key, existing);
            if (authMode === 'seller') {
              setSellerUser(refreshed);
              finishAuthSuccess('seller', refreshed);
            } else {
              setUser(refreshed);
              finishAuthSuccess('buyer', refreshed);
            }
          } else {
            setAuthStep('name');
          }
        }, 400);
      };

