                              <button type="button" onClick={() => { closeProfilePage(); openPDP(p); }} className="flex-shrink-0">
                                <img src={p.colors?.[0]?.image || p.image} alt="" className="w-16 h-20 object-cover rounded-lg" />
                              </button>
